$ec_lang['lpn_inp_drop_curve_missing']='यह पंप एक ऐसे वक्र का नाम लेता है जो फ़ाइल में नहीं है। यह बिना वक्र के आया, इसलिए यह कोई हेड नहीं जोड़ता।';
